    name: str
    method: str
    path: str
    scope: str
    profiles: tuple[str, ...]
    read_only: bool
    required_scopes: tuple[str, ...]
    idempotency: str
    idempotency_location: str | None
    idempotency_key_field: str | None
    idempotency_replay: str
    conversation_auth: str
    conversation_auth_fields: tuple[str, ...]


